    return word.size() - j;
}

code.c:
int lettersToAppend(const char* text, const char* word) {
    int j = 0, n = strlen(word);
    for (const char* p = text; *p != '\0'; p++) {
        if (j < n && *p == word[j])
            j++;
    }
    return n - j;
}

